modern_c2_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    container_patches = image_patch.find("container")
    peanut_butter_patches = image_patch.find("peanut butter")

    if not container_patches or not peanut_butter_patches:
        return image_patch

    container_patches.sort(key=lambda p: p.compute_depth(), reverse=True)
    peanut_butter_patches.sort(key=lambda p: p.compute_depth())

    container = container_patches[0]
    peanut_butter = peanut_butter_patches[0]

    if container.overlaps_with(peanut_butter.left, peanut_butter.lower, peanut_butter.right, peanut_butter.upper):
        return container

    container_center_x = (container.left + container.right) / 2
    container_center_y = (container.lower + container.upper) / 2
    peanut_butter_center_x = (peanut_butter.left + peanut_butter.right) / 2
    peanut_butter_center_y = (peanut_butter.lower + peanut_butter.upper) / 2

    if abs(container_center_x - peanut_butter_center_x) < abs(container_center_y - peanut_butter_center_y):
        if peanut_butter_center_x > container_center_x:
            return container.crop(container.right, container.lower, container.right + 100, container.upper)
        else:
            return container.crop(container.left - 100, container.lower, container.left, container.upper)
    else:
        if peanut_butter_center_y > container_center_y:
            return container.crop

