    image_patch = ImagePatch(image)
    chairs = image_patch.find("chair")
    desks = image_patch.find("desk")

    if not chairs or not desks:
        return image_patch

    dark_brown_chairs = [c for c in chairs if c.verify_property("chair", "dark brown")]
    brown_desks = [d for d in desks if d.verify_property("desk", "brown")]

    if not dark_brown_chairs or not brown_desks:
        return image_patch

    best_match = None
    min_distance = float('inf')

    for chair in dark_brown_chairs:
        for desk in brown_desks:
            if chair.overlaps_with(desk.left, desk.lower, desk.right, desk.upper):
                distance = abs(chair.vertical_center - desk.vertical_center)
                if distance < min_distance:
                    min_distance = distance
                    best_match = chair

    return best_match

