    man_patches = image_patch.find("man")
    horse_patches = image_patch.find("horse")

    if not man_patches or not horse_patches:
        return image_patch

    man_centers = [(p.left + p.right) / 2, (p.upper + p.lower) / 2 for p in man_patches]
    horse_centers = [(p.left + p.right) / 2, (p.upper + p.lower) / 2 for p in horse_patches]

    closest_horse = min(horse_centers, key=lambda h: min(abs(m - h) for m in man_centers))
    horse_idx = horse_centers.index(closest_horse)

    man_hold_patches = [p for p in man_patches if p.overlaps_with(*horse_patches[horse_idx])]
    man_walk_patches = [p for p in man_patches if abs(p.horizontal_center - closest_horse[0]) < abs(man_centers[0] - closest_horse[0])]

    if man_hold_patches and man_walk_patches:
        return man_hold_patches[0]
    elif man_hold_patches:
        return man_hold_patches[0]
    elif man_walk_patches:
        return man_walk_patches[0]
    else:
        return image_patch

